INSERT INTO blog_seo (slug, title, description, image_url, page_type) VALUES ('why-ev-charging-settlement-is-broken', 'Why EV Charging Settlement Is Broken — and What It Will Take to Fix It', 'EV charging settlement is broken because the financial layer was bolted on as an afterthought. Learn what card payments and telecoms teach us about fixing it.', 'https://networkcore.org/blog/why-ev-charging-settlement-is-broken.jpg', 'blog');